    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> t = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) t.add(st.nextToken());
        }
        String s = t.get(0);
        int q = Integer.parseInt(t.get(1));
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            queries[i][0] = Integer.parseInt(t.get(2 + 2 * i));
            queries[i][1] = Integer.parseInt(t.get(3 + 2 * i));
        }
        int[] res = countVowels(s, queries);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append("\n");
        System.out.print(sb);
    }
